import { mountPopBoards } from './components/dgn-pop-board.js';
import { createDgnWinnings } from './components/dgn-winnings.js';
import { dgnScore } from './app/dgn-reels.js';
import { isMuted, setMuted, warmup, sfxRollDone } from './app/jackpot-sfx.js';

// Presentation-only samples. These are not bets or claimed chain results.
const pack = traits => traits.reduce((word, [sym,col,wild], q) =>
  word | ((wild ? 0x40 | sym : col * 8 + sym) << (q * 8)), 0) >>> 0;
const player = pack([[6,0,true],[2,4],[5,2],[3,1]]);
const samples = {
  hit: { house: pack([[6,7],[1,4],[4,5],[2,4]]), payout: '1,500 FLIP', text: 'A clean hit. Score first, payout second.' },
  miss: { house: pack([[5,3],[1,2],[4,5],[2,4]]), payout: '0 FLIP', text: 'No payout. Keep the miss brief and clear.' },
  big: { house: player, payout: '9,000 FLIP', text: 'Strong hit. A brighter landing, one extra beat.' },
};
const names = { sweep:'QUICK SWEEP', flip:'SINGLE FLIP', manual:'TAP TO POP' };
const $ = selector => document.querySelector(selector);
const host = $('#lab-card'), stage = $('.lab-preview'), play = $('#lab-play'), batch = $('#lab-batch');
const sampleSelect = $('#lab-sample'), speedInput = $('#lab-speed'), verdict = $('#lab-verdict');
const timers = new Map();
let mode = 'sweep', pop, winnings, generation = 0, runningBatch = false, finished = false;
const speed = () => Number(speedInput.value);
const reduced = () => matchMedia('(prefers-reduced-motion: reduce)').matches;
const wait = (ms, token) => new Promise(resolve => {
  const timer = setTimeout(() => { timers.delete(timer); resolve(token === generation); }, ms / speed());
  timers.set(timer, resolve);
});
function cancel() {
  generation++;
  for (const [timer, resolve] of timers) { clearTimeout(timer); resolve(false); }
  timers.clear();
  runningBatch = false;
  batch.textContent = 'TRY 3 CARDS';
  play.disabled = false;
  stage.classList.remove('is-turning');
}
function mount(sample = sampleSelect.value, progress = 'SAMPLE CARD') {
  pop?.dispose(); winnings?.dispose(); host.textContent = '';
  finished = false;
  stage.dataset.phase = 'ready'; stage.dataset.big = String(sample === 'big');
  $('#lab-progress').textContent = progress;
  verdict.textContent = mode === 'manual' ? 'Tap a quadrant, or the flame for the whole card.' : 'Ready when you are.';
  play.textContent = mode === 'manual' ? 'REVEAL REST' : 'REVEAL CARD';
  const fixture = samples[sample];
  const row = {playerTraits:player,houseTraits:fixture.house,score:dgnScore(player,fixture.house)};
  winnings = createDgnWinnings(document);
  winnings.update('—', {caption:'CARD PAYOUT',detail:'Sample · before coin flip',duration:0});
  pop = mountPopBoards(host, [row], {
    footer:winnings.element,
    onChange(progress) {
      if (!progress.complete) {
        verdict.textContent = `${progress.score} ${progress.score === 1 ? 'point' : 'points'} revealed`;
        return;
      }
      finished = true;
      stage.dataset.phase = 'result';
      // Only the uncovered card exposes the sample payout. Keep it exact while reading.
      winnings.update(fixture.payout, {caption:'CARD PAYOUT',detail:'Sample · before coin flip',duration:0});
      verdict.textContent = `${row.score} POINTS · ${fixture.text}`;
      play.textContent = 'PLAY AGAIN'; play.disabled = false;
      sfxRollDone(sample !== 'miss');
    },
  });
}
async function reveal(token = generation) {
  if (mode === 'manual' || reduced()) { pop.revealAll(); return token === generation; }
  play.disabled = true;
  stage.dataset.phase = 'revealing';
  if (mode === 'sweep') {
    verdict.textContent = 'Watch the matches build.';
    for (const q of [0,1,3,2]) {
      if (token !== generation) return false;
      pop.reveal(0,1 << q);
      if (!await wait(170,token)) return false;
    }
  } else {
    stage.style.setProperty('--lab-flip-ms', `${160 / speed()}ms`);
    stage.classList.add('is-turning');
    if (!await wait(160,token)) return false;
    pop.revealAll();
    stage.classList.remove('is-turning');
    if (!await wait(160,token)) return false;
  }
  return token === generation;
}
play.addEventListener('click', async () => {
  warmup(); cancel();
  if (finished) mount();
  await reveal();
});
batch.addEventListener('click', async () => {
  warmup();
  if (runningBatch) { cancel(); verdict.textContent = 'Batch stopped. This card stays here to inspect.'; return; }
  cancel(); runningBatch = true; batch.textContent = 'STOP BATCH';
  const token = generation;
  for (const [i,sample] of ['miss','hit','big'].entries()) {
    mount(sample,`CARD ${i + 1} OF 3`);
    if (!await reveal(token)) return;
    if (!await wait(3500 + (sample === 'big' ? 350 : 0),token)) return;
  }
  runningBatch = false; batch.textContent = 'TRY 3 CARDS';
  verdict.textContent = 'Batch complete. Try another reveal style.';
});
for (const button of document.querySelectorAll('[data-mode]')) button.addEventListener('click', () => {
  cancel(); mode = button.dataset.mode;
  for (const item of document.querySelectorAll('[data-mode]')) item.setAttribute('aria-pressed', String(item === button));
  $('#lab-mode-name').textContent = names[mode];
  batch.disabled = mode === 'manual';
  mount();
});
sampleSelect.addEventListener('change', () => { cancel(); mount(); });
speedInput.addEventListener('input', () => {
  $('#lab-speed-value').textContent = `${speed()}×`;
  $('#lab-hold').textContent = `Autoplay result hold: ${(3.5 / speed()).toFixed(1)}s`;
});
$('#lab-sound').checked = !isMuted();
$('#lab-sound').addEventListener('change', event => { setMuted(!event.target.checked); warmup(); });
window.addEventListener('pagehide', () => { cancel(); pop?.dispose(); winnings?.dispose(); });
mount();
